item.command:
/bin/zsh -lc "cat > tb.sv <<'EOF'
"'`timescale 1ns/1ps
module tb;
  reg clk = 0;
  reg rst_n = 1;
  reg set = 0;
  reg [3:0] set_num = 0;
  wire [3:0] number;
  wire zero;

  TopModule dut(.clk(clk), .rst_n(rst_n), .set(set), .set_num(set_num), .number(number), .zero(zero));

  always #5 clk = ~clk;

  initial begin
    $display("time clk rst_n set set_num | number zero");
    $monitor("%4t   %0b    %0b    %0b    %h   |   %h     %0b", $time, clk, rst_n, set, set_num, number, zero);
    rst_n = 0;
    #2;
    rst_n = 1;
    repeat (18) @(posedge clk);
    set = 1; set_num = 4'"'h0;
    @(posedge clk);
    set = 0;
    repeat (3) @(posedge clk);
    "'$finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

